49	    public record CurtailmentResponse(long id, long windowId, String volume, String status,
50	                                      String createdUtc, String cancelledUtc) {
51	    }
52	
53	    /** 窗口当前可用容量视图；approvedTotal 汇总 APPROVED 申请的当前持有额度。 */
54	    public record CapacityResponse(long windowId, String plannedVolume, String activeCurtailmentVolume,
55	                                   String availableTotal, String approvedTotal, String remaining) {
56	    }
57	
58	    /** 同窗口额度转让命令；操作人（源申请人）由 X-Actor-Id 请求头提供。 */
59	    public record TransferRequest(String commandKey, String transferKey, String sourceAllocationKey,
60	                                  String targetAllocationKey) {
61	    }
62	
63	    /** 转让流水视图，创建后不可变，不提供撤销。 */
64	    public record TransferResponse(String transferKey, long windowId, String sourceAllocationKey,
65	                                   String targetAllocationKey, String amount, String actor, String createdUtc) {
66	    }
67	
68	    /** 窗口转让流水列表视图。 */
69	    public record TransferListResponse(long windowId, List<TransferResponse> transfers) {
70	    }
71	
72	    /** 窗口历史明细：窗口本身 + 全部申请 + 全部限供记录。 */
73	    public record HistoryResponse(WindowResponse window, List<AllocationResponse> allocations,
74	                                  List<CurtailmentResponse> curtailments) {
75	    }
76	
77	    /** 统一错误响应体。 */
78	    public record ErrorResponse(String code, String message) {
79	    }
80	}
