        throw ApiException.badRequest("INVALID_ARGUMENT", "windowId 不能为空");
    }
    BigDecimal qty = parseAmount("amount", amount);
    String params = "ALLOCATION_SUBMIT|" + allocationKey + "|" + windowId + "|" + userId + "|"
